out vec4 color;

#define PI 3.1415926
#define TAU 6.2831853

%%sunspots%%

vec3 sdgCircle( in vec2 p, in float r ) {
    float d = length(p);
    return vec3( d-r, p/d );
}

float smin( float a, float b, float k ){
    float res = exp2( -k*a ) + exp2( -k*b );
    return -log2( res )/k;
}

vec3 sdgSmoothMin( in vec3 a, in vec3 b, in float k ){
    float h = max(k-abs(a.x-b.x),0.0);
    float m = 0.25*h*h/k;
    float n = 0.50*  h/k;
    return vec3( min(a.x,  b.x) - m, 
                 mix(a.yz, b.yz, (a.x<b.x)?n:1.0-n) );
}

float getHaversine( vec2 p0, vec2 p1 ){
    vec2 c = u_sunPos;
    float sr = u_sunRad;
    float d0 = distance( c, p0 );
    float d1 = distance( c, p1 );
    float r0 = clamp( d0/sr, 0.0, 1.0 );
    float r1 = clamp( d1/sr, 0.0, 1.0 );

    r0 = pow( 1.0 - r0, 0.25 ) * sr * 2.0;
    r1 = pow( 1.0 - r1, 0.25 ) * sr * 2.0;

    vec3 ps0 = vec3( p0, r0 );
    vec3 ps1 = vec3( p1, r1 );

    float hd = distance( ps0, ps1 );
    return hd;
}

// Hash without Sine
// MIT License...
// Copyright (c)2014 David Hoskins.

#define OCTAVES 8
#define UI0 1597334673U
#define UI1 3812015801U
#define UI2 uvec2(UI0, UI1)
#define UIF (1.0 / float(0xffffffffU))
float hash12(vec2 p){
	uvec2 q = uvec2(ivec2(p)) * UI2;
	uint n = (q.x ^ q.y) * UI0;
	return float(n) * UIF;
}

/*float hash12( vec2 p ){
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}*/

vec4 getForceData( vec2 p, float sr ){
    vec2 c = u_sunPos;
    float t = hash12( p ) * TAU;
    float r = sr - hash12( p + u_nOff ) * sr * 0.05;
    float x = c.x + cos( t ) * r;
    float y = c.y + sin( t ) * r;
    float f = hash12( p * vec2( 155.0 ) + u_nOff ) - 0.5;

    return vec4( x, y, hash12( p + vec2( 2.3, 5.6 ) ), f );
}

void main() {
    vec2 dirToSun = u_sunPos - gl_FragCoord.xy;
    vec3 sunSdg = sdgCircle( dirToSun, u_sunRad );
    float sunDist = sunSdg.x;

    float myDist = 1000000.0;
    vec3 mySdg = vec3( 100000.0, 0.0, 0.0 ); 
	vec2 myVel = vec2( 0.0, 0.0 );
	float myF = 0.0;
    float myR = 0.0;
	vec2 p0 = gl_FragCoord.xy;

    if( sunDist > 0.0 ){
        for( int i=0; i<u_numForces; i++ ){
            float u         = hash12( vec2( float( i ) * 3.3 + 11.4, 0.5 ) );
            float v         = hash12( vec2( float( i ) * 5.5 + 17.5, 0.5 ) );
            vec4 forceData  = getForceData( vec2( u, v ) * 100.0, u_sunRad );
            vec2 p1         = forceData.xy;
            float r         = forceData.z;
            float f         = forceData.w;

            vec2 dir 		= p0 - p1;
            float dist 		= length( dir );
            vec2 dirNorm    = normalize( dir );
            float distSq    = dist * dist;
            float invDistSq = 1.0 / ( distSq + r );

            myVel += dirNorm * invDistSq * 5000.0 * f;

            if( dist < myDist ){
                myDist = dist;
                myF     = f;
            }
        }
    } else {
        for( int i=0; i<u_numSpots; i++ ){
            vec4 spot       = spots[i];
            vec2 p1         = spot.xy;
            float r         = spot.z;
            float f         = spot.w;

            vec2 dir 		= p0 - p1;
            float dist      = getHaversine( p0, p1 );
            vec3 sdg        = sdgCircle( dir, r );
            vec2 dirNorm    = normalize( dir );
            float distSq    = dist * dist;
            float invDistSq = 1.0 / ( distSq + r );
            sdg.x           = dist;
            mySdg           = sdgSmoothMin( sdg, mySdg, u_sunRad * 0.05 );
            myF             = smin( myF, f, 35.0 ) * sign( f );
            myR             = smin( myR, r, 35.0 );
            myVel += dirNorm * invDistSq * 500.0 * f;
        }
        myDist = mySdg.x;
